CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120),created_by text NOT NULL DEFAULT current_setting('app.actor_id',true),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(tenant_id uuid NOT NULL REFERENCES tenants,user_id text NOT NULL,role text NOT NULL CHECK(role IN('owner','editor','viewer')),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','revoked')),PRIMARY KEY(tenant_id,user_id));
CREATE FUNCTION can_access_tenant(tid uuid,write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM memberships WHERE tenant_id=tid AND user_id=current_setting('app.actor_id',true) AND state='active' AND (NOT write OR role IN('owner','editor'))) $$;
CREATE FUNCTION is_tenant_owner(tid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM memberships WHERE tenant_id=tid AND user_id=current_setting('app.actor_id',true) AND state='active' AND role='owner') $$;
CREATE FUNCTION owns_new_tenant(tid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM tenants WHERE id=tid AND created_by=current_setting('app.actor_id',true)) AND NOT EXISTS(SELECT 1 FROM memberships WHERE tenant_id=tid) $$;
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_read ON tenants FOR SELECT USING(can_access_tenant(id) OR created_by=current_setting('app.actor_id',true));
CREATE POLICY tenant_create ON tenants FOR INSERT WITH CHECK(created_by=current_setting('app.actor_id',true) AND length(created_by)>0);
CREATE POLICY tenant_update ON tenants FOR UPDATE USING(is_tenant_owner(id)) WITH CHECK(is_tenant_owner(id));
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
-- SECURITY DEFINER authorization functions are owned by migration superuser; runtime cannot replace them.
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY membership_read ON memberships FOR SELECT USING(user_id=current_setting('app.actor_id',true) OR is_tenant_owner(tenant_id));
CREATE POLICY membership_insert ON memberships FOR INSERT WITH CHECK(is_tenant_owner(tenant_id) OR (owns_new_tenant(tenant_id) AND user_id=current_setting('app.actor_id',true) AND role='owner' AND state='active'));
CREATE POLICY membership_update ON memberships FOR UPDATE USING(is_tenant_owner(tenant_id)) WITH CHECK(is_tenant_owner(tenant_id));
CREATE TABLE profiles(user_id text PRIMARY KEY,body jsonb NOT NULL DEFAULT '{}',revision int NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE profiles FORCE ROW LEVEL SECURITY;
CREATE POLICY profile_own ON profiles USING(user_id=current_setting('app.actor_id',true)) WITH CHECK(user_id=current_setting('app.actor_id',true));
CREATE TABLE places(id text PRIMARY KEY,slug text UNIQUE NOT NULL,name text NOT NULL,category text NOT NULL,city text NOT NULL DEFAULT 'Hyderabad',neighborhood text NOT NULL,address text NOT NULL,summary text NOT NULL,tags jsonb NOT NULL DEFAULT '[]',source_urls jsonb NOT NULL DEFAULT '[]',researched_at text NOT NULL,search_query text NOT NULL,catalog_data jsonb NOT NULL DEFAULT '{}',point geography(Point,4326),point_kind text,point_source text,state text NOT NULL DEFAULT 'research',revision int NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX places_point_idx ON places USING gist(point);
CREATE INDEX places_search_idx ON places USING gin(to_tsvector('simple',name||' '||neighborhood||' '||summary));
ALTER TABLE places ENABLE ROW LEVEL SECURITY;ALTER TABLE places FORCE ROW LEVEL SECURITY;
CREATE POLICY places_public_read ON places FOR SELECT USING(state IN('research','published','closed'));
CREATE TABLE audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id text NOT NULL,tenant_id uuid REFERENCES tenants,action text NOT NULL,target_id text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;ALTER TABLE audit_log FORCE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON audit_log FOR SELECT USING(can_access_tenant(tenant_id));
CREATE POLICY audit_insert ON audit_log FOR INSERT WITH CHECK(actor_id=current_setting('app.actor_id',true));
CREATE TABLE idempotency(actor_id text NOT NULL,scope text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,scope,key));
ALTER TABLE idempotency ENABLE ROW LEVEL SECURITY;ALTER TABLE idempotency FORCE ROW LEVEL SECURITY;
CREATE POLICY idempotency_own ON idempotency USING(actor_id=current_setting('app.actor_id',true)) WITH CHECK(actor_id=current_setting('app.actor_id',true));
CREATE TABLE quota_buckets(key text NOT NULL,window_start timestamptz NOT NULL,count int NOT NULL,PRIMARY KEY(key,window_start));
CREATE FUNCTION consume_quota(qkey text,qmax int,qseconds int) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE n int; w timestamptz; BEGIN IF qmax<1 OR qseconds<1 THEN RETURN false; END IF; w:=to_timestamp(floor(extract(epoch FROM now())/qseconds)*qseconds); INSERT INTO quota_buckets(key,window_start,count) VALUES(qkey,w,1) ON CONFLICT(key,window_start) DO UPDATE SET count=quota_buckets.count+1 WHERE quota_buckets.count<qmax RETURNING count INTO n; RETURN n IS NOT NULL; END $$;
